#!/usr/bin/env python3
"""Patch the iOS runner generated by `flutter create --platforms=ios`.

The repository does not commit the platform runners yet. CI generates ios/
and this script applies the SARCADE-specific settings to Runner/Info.plist:

- usage texts for location (geolocator), local network, photo library and camera,
  required by iOS before the system shows its permission prompts
- App Transport Security exception for plain HTTP/WS, needed while the V0.1
  server is reached as http://IP:8000 on a LAN (same as cleartext on Android)
- display name "SARCADE"; no non-exempt encryption (HTTPS only), so
  TestFlight does not ask the export question for every build
- Apple team of SDUBOS Consulting on the Runner target (automatic signing)
- SARCADE icon (single 1024 px image, Xcode derives the other sizes)
- push notifications (wake-up by Firebase / APNs): aps-environment
  entitlement and the remote-notification background mode

Idempotent, and fails loudly if the template changed shape.
"""
import json
import plistlib
import subprocess
import sys
from pathlib import Path

PLIST = Path("ios/Runner/Info.plist")
PBXPROJ = Path("ios/Runner.xcodeproj/project.pbxproj")
ICONSET = Path("ios/Runner/Assets.xcassets/AppIcon.appiconset")
TEAM = "34785R7XLK"
BUNDLE_LINE = "PRODUCT_BUNDLE_IDENTIFIER = org.sarcade.sarcadeApp;"
ENTITLEMENTS = Path("ios/Runner/Runner.entitlements")
ENTITLEMENTS_XML = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>aps-environment</key><string>production</string>
</dict></plist>
"""

USAGE = {
    "NSLocationWhenInUseUsageDescription":
        "SARCADE partage votre position avec le poste de commandement pendant l’événement, y compris quand la balise tourne en arrière-plan.",
    "NSLocalNetworkUsageDescription":
        "SARCADE se connecte au serveur de l’événement sur le réseau local, même sans Internet.",
    "NSPhotoLibraryUsageDescription":
        "SARCADE permet de joindre des photos aux messages et aux fichiers partagés de l’événement.",
    "NSMicrophoneUsageDescription":
        "SARCADE utilise le micro pour dicter une recherche ou un message.",
    "NSSpeechRecognitionUsageDescription":
        "SARCADE transforme votre voix en texte pour dicter une recherche ou un message.",
    "NSCameraUsageDescription":
        "SARCADE permet de prendre une photo et de l’envoyer en message au poste de commandement.",
}


def main() -> int:
    if not PLIST.exists():
        print(f"error: {PLIST} not found, run flutter create first", file=sys.stderr)
        return 1
    with PLIST.open("rb") as f:
        info = plistlib.load(f)
    if "CFBundleIdentifier" not in info:
        print("error: unexpected Info.plist content", file=sys.stderr)
        return 1
    info.update(USAGE)
    info["CFBundleDisplayName"] = "SARCADE"
    info["ITSAppUsesNonExemptEncryption"] = False
    modes = info.setdefault("UIBackgroundModes", [])
    for mode in ("remote-notification", "location"):
        if mode not in modes:
            modes.append(mode)
    ats = info.setdefault("NSAppTransportSecurity", {})
    ats["NSAllowsArbitraryLoads"] = True
    ats["NSAllowsLocalNetworking"] = True
    with PLIST.open("wb") as f:
        plistlib.dump(info, f)
    print(f"patched {PLIST}")

    proj = PBXPROJ.read_text()
    if BUNDLE_LINE not in proj:
        print(f"error: {BUNDLE_LINE} not found in {PBXPROJ}", file=sys.stderr)
        return 1
    ENTITLEMENTS.write_text(ENTITLEMENTS_XML)
    if f"DEVELOPMENT_TEAM = {TEAM};" not in proj:
        lines = []
        for line in proj.splitlines(keepends=True):
            if line.strip() == BUNDLE_LINE:
                indent = line[: len(line) - len(line.lstrip())]
                lines.append(f"{indent}DEVELOPMENT_TEAM = {TEAM};\n")
                lines.append(f"{indent}CODE_SIGN_ENTITLEMENTS = Runner/Runner.entitlements;\n")
            lines.append(line)
        PBXPROJ.write_text("".join(lines))
    print(f"patched {PBXPROJ} (team {TEAM})")

    for old in ICONSET.glob("*.png"):
        old.unlink()
    subprocess.run([sys.executable, "tool/make_icon.py", str(ICONSET / "icon-1024.png"), "1024"], check=True)
    (ICONSET / "Contents.json").write_text(json.dumps({
        "images": [{"filename": "icon-1024.png", "idiom": "universal", "platform": "ios", "size": "1024x1024"}],
        "info": {"author": "xcode", "version": 1}}, indent=2))
    print(f"patched {ICONSET}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
